/**
 * Infinite grid mesh with anti-aliased lines and dual-layer composition.
 *
 * **Features**
 * - Two independent grid layers (A and B) with configurable cell size, width, color, and opacity
 * - Analytic derivative-based rendering keeps line thickness stable across all zoom levels
 * - World-space positioning using positionWorld (grid doesn't move with camera)
 * - Smooth anti-aliasing at any distance or angle
 * - Full TSL/NodeMaterial implementation for WebGPU compatibility
 *
 * **Rendering**
 * - Uses fragment shader derivatives (dFdx/dFdy) to compute pixel-space line width
 * - Lines automatically adapt thickness based on screen-space density
 * - Composite blend: background → layer B → layer A
 * - No texture lookups or geometry subdivision required
 *
 * **Use Cases**
 * - Scene reference grids with major/minor divisions
 * - CAD/3D editor floor grids
 * - Architectural visualization ground planes
 * - Debug visualizations requiring stable grid lines
 *
 * ```js
 * import { GridPristine } from '@three-blocks/core';
 * import * as THREE from 'three/webgpu';
 *
 * // Basic grid with default settings
 * const grid = new GridPristine();
 * scene.add(grid);
 *
 * @demo docs/demos/grid-pristine.html
 * @class GridPristine
 * @tags WebGPU, WebGL
 * @extends THREE.Mesh
 * @short Infinite anti-aliased grid mesh with two configurable layers rendered analytically in world space.
 * @category Meshes
 */
export class GridPristine {
    /**
     * Create an infinite grid mesh.
     *
     * @param {Object} [params] - Grid configuration options.
     * @param {number} [params.width=9999] Plane width in world units.
     * @param {number} [params.height=9999] Plane height in world units.
     * @param {number} [params.cellSizeA=10.0] Cell size for layer A (world units).
     * @param {number} [params.lineWidthA=0.03] Line width for layer A (world units).
     * @param {number|string|THREE.Color} [params.colorA=0xffffff] Line color for layer A.
     * @param {number} [params.opacityA=1.0] Opacity for layer A in [0,1].
     * @param {number} [params.cellSizeB=1.0] Cell size for layer B (world units).
     * @param {number} [params.lineWidthB=0.02] Line width for layer B (world units).
     * @param {number|string|THREE.Color} [params.colorB=0xcccccc] Line color for layer B.
     * @param {number} [params.opacityB=0.45] Opacity for layer B in [0,1].
     * @param {number|string|THREE.Color} [params.bgColor=0x000000] Background color.
     */
    constructor(params?: {
        width?: number;
        height?: number;
        cellSizeA?: number;
        lineWidthA?: number;
        colorA?: number | string | THREE.Color;
        opacityA?: number;
        cellSizeB?: number;
        lineWidthB?: number;
        colorB?: number | string | THREE.Color;
        opacityB?: number;
        bgColor?: number | string | THREE.Color;
    });
    geometry: THREE.PlaneGeometry;
    material: THREE.NodeMaterial;
    cellSizeA: any;
    lineWidthA: any;
    colorA: any;
    opacityA: any;
    cellSizeB: any;
    lineWidthB: any;
    colorB: any;
    opacityB: any;
    bgColor: any;
    /**
 * Computes a single-axis grid mask in CELL units.
 * @private
 * @type {*}
 */
    private computeMask;
    /**
 * Computes an intersection-only mask ("+") at grid crossings.
 * @private
 * @type {*}
 */
    private computePlusMask;
    /**
 * Fragment node composing both layers over the background.
 * @private
 * @type {*}
 */
    private fragmentMain;
    /**
      * Attach a GUI folder with common controls.
      * Compatible with lil-gui, dat.gui, and Three.js Inspector.
      * @param {*} gui - GUI instance (e.g., lil-gui/dat.gui or renderer.inspector.createParameters()).
      * @returns {GridPristine}
      */
    attachGUI(gui: any): GridPristine;
    _debug: any;
    /**
   * Detach and destroy the GUI folder.
   * @returns {GridPristine}
   */
    disposeGUI(): GridPristine;
    /**
   * Dispose GPU resources and detach GUI.
   * @returns {void}
   */
    dispose(): void;
}
